// src/components/common/TransactionForm.jsx
import React, { useState, useEffect } from 'react';
import { extractDateFromTransactionId } from '../../utils/helpers.js';
import './TransactionForm.css';

const TransactionForm = ({ 
  title, 
  isReplacement, 
  txData, 
  onChange, 
  onSubmit, 
  onCancel,
  isPending = false,
  representative
}) => {
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    onChange({ target: { name, value } });
  };

  // Auto-extract date when transaction ID changes
  const handleTxIdChange = (e) => {
    const value = e.target.value;
    onChange({ target: { name: 'txId', value } });
    
    // Extract date from transaction ID
    if (value && value.length >= 8) {
      const extractedDate = extractDateFromTransactionId(value);
      if (extractedDate) {
        onChange({ target: { name: 'date', value: extractedDate } });
      }
    }
  };

  return (
    <div className="claim-card transaction-container">
      <div className="transaction-title">{title}</div>
      <div className="tx-form">
        {isPending ? (
          <div className="field">
            <label>Transaction Amount</label>
            <div className="status-pending">⏳ Pending (Customer Care)</div>
            <div className="helper-text">Customer care will fill the amount</div>
          </div>
        ) : isReplacement ? (
          <div className="field">
            <label>Transaction Amount *</label>
            <input
              type="text"
              name="amount"
              value={txData.amount}
              onChange={handleInputChange}
              placeholder="e.g., 250000"
              required
            />
          </div>
        ) : (
          <div className="field">
            <label>Transaction Amount</label>
            <div className="status-pending">Amount Pending (Customer Care)</div>
          </div>
        )}
        
        <div className="field">
          <label>Transaction ID *</label>
          <input
            type="text"
            name="txId"
            value={txData.txId}
            onChange={handleTxIdChange}
            placeholder="e.g., MP260610.2000.X08195"
            required
          />
          
        </div>
        
        <div className="field">
          <label>Transaction Date</label>
          <input
            type="text"
            name="date"
            value={txData.date}
            readOnly
            className="readonly"
          />
          {txData.date && txData.date !== 'Invalid Date' && (
            <div className="helper-text success">
              <i className="fas fa-check-circle"></i> 
              Date auto-extracted from Transaction ID
            </div>
          )}
        </div>
        
        <div className="field">
          <label>Representative</label>
          <input
            type="text"
            value={representative || 'Shabani'}
            disabled
            className="readonly"
          />
        </div>
        
        <div className="form-actions">
          <button type="button" className="btn-outline" onClick={onCancel}>Cancel</button>
          <button 
            type="button" 
            className="submit-btn" 
            onClick={onSubmit}
            disabled={!txData.txId || (!isPending && isReplacement && !txData.amount)}
          >
            <i className="fas fa-check"></i> 
            {isPending ? 'Send to Customer Care' : 'Submit'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default TransactionForm;
